<script setup>
import {dramaImages} from './images.js';
import DramaImageGallery from './DramaImageGallery.vue';
import CalendarSectionHeading from '../components/CalendarSectionHeading.vue';
import {resolvePlatformLogo,matchedPlatform} from './platforms.js';
const platformLogo=p=>resolvePlatformLogo(p,import.meta.env.BASE_URL);
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';
import DramaSubmission from './DramaSubmission.vue';
import {initialData} from './seed.js';
import {generateSchedule,dramaTitle,announcementsForEpisode} from './schedule.js';
const submissionOpen=ref(false);
const key='chob-drama-private-v1';
let saved;try{saved=JSON.parse(localStorage.getItem(key));}catch{}
const props=defineProps({embedded:Boolean,scheduleArtists:{type:Array,default:()=>[]},loadSnapshot:{type:Function,default:null}});
const db=ref(props.loadSnapshot?{dramas:[],changes:[],events:[],platforms:[],artists:[]}:saved?.dramas && saved?.platforms && saved?.events && saved?.changes && saved?.artists?saved:structuredClone(initialData));
const storageError=ref('');
let polling;async function refresh(){try{if(props.loadSnapshot){db.value=await props.loadSnapshot();}else{const response=await fetch('/__drama_test_data');if(!response.ok)throw Error('测试数据读取失败');db.value=await response.json();}storageError.value='';}catch(e){storageError.value=e.message;}}onMounted(()=>{refresh();polling=setInterval(refresh,props.loadSnapshot?30000:2000);});onBeforeUnmount(()=>clearInterval(polling));


const tab=ref('calendar'),month=ref('2026-11'),search=ref(''),selected=ref(null),error=ref(''),notice=ref(''),eventSelected=ref(null),unused=ref(null);

const title=dramaTitle;
function safe(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
const filtered=computed(()=>db.value.dramas.filter(d=>[d.titleZh,d.titleEn,d.titleTh,...d.types].join(' ').toLowerCase().includes(search.value.toLowerCase())));
const slots=computed(()=>{const out=[];for(const d of db.value.dramas)for(const r of d.rules){let rows=generateSchedule(d,r);for(const c of db.value.changes.filter(c=>c.original.dramaId===d.id&&c.original.ruleId===r.id)){rows=rows.map(s=>s.id===c.original.id?c.original:s);rows.push(c.replacement);}out.push(...rows);}return out;});
const days=computed(()=>{if(!month.value)return [];const start=new Date(month.value+'-01T00:00:00Z');const count=new Date(Date.UTC(start.getUTCFullYear(),start.getUTCMonth()+1,0)).getUTCDate();return [...Array(start.getUTCDay()).fill(null),...Array.from({length:count},(_,i)=>`${month.value}-${String(i+1).padStart(2,'0')}`)];});
const notices=computed(()=>selected.value?.slot?announcementsForEpisode(db.value.changes.map(c=>c.announcement),selected.value.drama.id,selected.value.slot.episode):db.value.changes.filter(c=>c.announcement.dramaId===selected.value?.drama.id).map(c=>c.announcement));
function drama(id){return db.value.dramas.find(d=>d.id===id);}
function platform(id){return db.value.platforms.find(p=>p.id===id)||{name:id};}
function status(d){const rows=slots.value.filter(s=>s.dramaId===d.id&&s.status!=='changed');if(!rows.length)return d.production;if(rows.every(s=>s.date<new Date().toISOString().slice(0,10)))return '已完播';return rows.some(s=>s.date<=new Date().toISOString().slice(0,10))?'播出中':'待播';}
function open(d,slot=null){selected.value={drama:d,slot};}
const chineseMonths=['一月','二月','三月','四月','五月','六月','七月','八月','九月','十月','十一月','十二月'];
const englishMonths=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function shiftMonth(n){const d=new Date(month.value+'-01T00:00:00Z');d.setUTCMonth(d.getUTCMonth()+n);month.value=d.toISOString().slice(0,7);}
</script>
<template>
<div class="shell"><header v-if="!embedded"><a class="brand" href="#">CHOB<span>CALENDAR</span></a><span class="private">私人测试 · 隔离数据</span></header>
<main><div class="drama-heading-row"><div class="drama-heading-controls"><nav><button v-for="(label,id) in {calendar:'播出月历',library:'剧集库'}" :class="{active:tab===id}" @click="tab=id">{{label}}</button></nav><div v-if="tab==='calendar'" class="drama-month-heading"><button class="arrow" aria-label="上个月" @click="shiftMonth(-1)">‹</button><div><span class="year">{{month.slice(0,4)}}</span><h2>{{chineseMonths[Number(month.slice(5))-1]}}<small>{{englishMonths[Number(month.slice(5))-1]}}</small></h2></div><button class="today" @click="month=new Date().toISOString().slice(0,7)">今天</button><button class="arrow" aria-label="下个月" @click="shiftMonth(1)">›</button></div></div><div class="drama-heading-brand"><CalendarSectionHeading word="Drama" chinese="追剧日历" eyebrow="STORIES, ONE DAY AT A TIME" description="把每一次相遇，放进日历。" /></div></div>

<p v-if="loadSnapshot" class="muted">管理员私有数据库预览 · 未公开发布 <button @click="refresh">刷新资料</button></p><p v-if="storageError" role="alert">{{storageError}}</p><p v-if="notice" role="status">{{notice}}</p>
<section v-if="tab==='calendar'"><div class="calendar"><b v-for="w in ['日','一','二','三','四','五','六']" class="weekday">{{w}}</b><div v-for="(day,index) in days" :key="day||index" class="day" :class="{blank:!day}"><span class="day-number">{{day?Number(day.slice(-2)):''}}</span><template v-if="day"><button v-for="s in slots.filter(s=>s.date===day)" :key="s.id" class="chip" :class="{changed:s.status==='changed'}" @click="open(drama(s.dramaId),s)"><span :class="{strike:s.status==='changed'}">{{title(drama(s.dramaId))}} · EP.{{s.episode}}</span><span v-if="s.status==='changed'"> · 剧集变动</span></button></template></div></div></section>
<section v-if="tab==='library'"><div class="toolbar"><input v-model="search" placeholder="搜索剧名、类型" aria-label="搜索剧集"><span>{{filtered.length}} 部剧集</span></div><div class="cards"><article v-for="d in filtered" :key="d.id" class="card"><button class="card-main" @click="open(d)"><img v-if="dramaImages(d)[0]" :src="dramaImages(d)[0]" alt="剧集海报"><div v-else class="poster">CHOB<br>DRAMA</div><div><span class="badge">{{status(d)}}</span><h2>{{title(d)}}</h2><p>{{d.titleEn}}</p><p class="muted">{{d.types.join(' · ')}}</p><p>{{d.cast.map(c=>c.name).join('、')||'Cast 待公布'}}</p></div></button></article></div><p v-if="!filtered.length">暂无匹配剧集</p></section>


</main><button class="drama-add" @click="submissionOpen=true" aria-label="新增剧集" title="新增剧集">＋</button><DramaSubmission :schedule-artists="scheduleArtists" v-if="submissionOpen" @close="submissionOpen=false" />
<div v-if="selected" class="overlay" @click.self="selected=null"><section class="dialog" role="dialog" aria-modal="true" aria-label="剧集详情" tabindex="-1" @keydown.esc="selected=null"><button class="close" @click="selected=null">关闭 ×</button><div class="hero"><div v-if="!dramaImages(selected.drama).length" class="poster-placeholder">海报待公布</div><DramaImageGallery :drama="selected.drama" /><div v-if="selected.slot?.status==='changed'" class="banner"><strong>剧集变动</strong><span>{{notices.find(n=>n.id===selected.slot.announcementId)?.content}}</span></div></div><span class="badge">{{status(selected.drama)}}</span><h2>{{title(selected.drama)}}</h2><p>{{selected.drama.types.join(' · ')}}</p><p>{{selected.drama.synopsis}}</p><p v-if="selected.drama.productionCompany">出品公司：{{selected.drama.productionCompany}}</p><h3 v-if="selected.slot">EP.{{selected.slot.episode}} · {{selected.slot.date}}</h3><p v-if="selected.slot" class="platform"><img v-if="platformLogo(platform(selected.slot.platformId))" :src="platformLogo(platform(selected.slot.platformId))" alt="">{{platform(selected.slot.platformId).name}} · {{selected.slot.time}} · {{selected.slot.timezone}} <small>{{selected.slot.confidence==='calculated'?'系统推算':'已确认'}}</small></p><aside v-for="n in notices" class="announcement"><strong>剧集变动 · EP.{{n.affectedEpisodes.join('、')}}</strong><p>{{n.content}}</p><small>原定 {{n.originalDate}} → 调整后 {{n.updatedDate}}</small></aside><h3>Cast</h3><p v-for="c in selected.drama.cast">{{c.name}} 饰 {{c.role||'待公布'}}</p><a v-if="safe(selected.drama.source)" :href="safe(selected.drama.source)" target="_blank" rel="noopener noreferrer">官方来源 ↗</a><h3>Press Tour / 观影活动</h3><button v-for="e in db.events.filter(e=>e.dramaId===selected.drama.id)" class="event-row" @click="eventSelected=e">{{e.date}} · {{e.name}} ↗ Calendar</button></section></div>
<div v-if="eventSelected" class="overlay" @click.self="eventSelected=null"><section class="dialog" role="dialog" aria-modal="true" aria-label="Calendar 活动详情"><button class="close" @click="eventSelected=null">关闭 ×</button><p class="eyebrow">CALENDAR · {{eventSelected.type}}</p><h2>{{eventSelected.name}}</h2><p>{{eventSelected.date}} {{eventSelected.time}}</p><p>{{eventSelected.location}}</p><button @click="open(drama(eventSelected.dramaId));eventSelected=null">查看关联剧集 ↗</button></section></div>
<footer>CHOB CALENDAR · DRAMA V1 <span>隔离预览 / 非正式数据</span></footer></div>
</template>
<style scoped>
