r:0;border-left:3px solid #8ca37b;border-radius:4px}.chip small{display:block;font-size:10px}.changed{background:#f7e9e2;border-color:#c69077}.strike{text-decoration:line-through}.event{background:#f1ecf7;border-color:#a48cbf}.cards{display:grid;grid-template-columns:repeat(2,1fr);gap:22px}.card{background:white;padding:18px;border:1px solid #e1e5dc;border-radius:12px}.card-main{display:flex;gap:22px;text-align:left;width:100%;border:0;padding:0;background:none}.card-main img,.poster{width:115px;height:160px;object-fit:cover;border-radius:6px;flex-shrink:0}.poster{background:linear-gradient(145deg,#bdcbb4,#758d75);color:white;display:grid;place-content:center;text-align:center;font:20px Georgia;letter-spacing:3px}.badge{font-size:11px;background:#edf1e6;padding:4px 9px;border-radius:20px}.card h2{font-size:20px;margin:10px 0}.card p{font-size:12px;margin:5px 0}.card>button:last-child{margin-top:12px;font-size:12px}.overlay{position:fixed;inset:0;background:#16261f66;display:flex;align-items:center;justify-content:center;z-index:10;padding:24px}.dialog{position:relative;background:#fff;border-radius:14px;padding:32px;width:650px;max-height:90vh;overflow:auto;box-shadow:0 20px 80px #14271d44}.close{float:right}.hero{position:relative;clear:both}.hero img{width:100%;max-height:280px;object-fit:contain}.banner{background:#f0d9c9;padding:16px;margin:18px 0}.banner strong{display:block;font-size:18px}.banner span{font-size:15px}.announcement{background:#f3e8db;border-radius:8px;padding:15px;margin:15px 0}.announcement p{margin:7px 0}.platform{display:inline-flex;align-items:center;gap:4px;flex-wrap:wrap}.platform img{height:16px;width:auto;max-width:70px;object-fit:contain}.editor label{display:flex;flex-direction:column;gap:5px;margin:12px 0}.editor .inline{display:inline-flex;flex-direction:row;margin-right:14px;align-items:center}.editor input[type=checkbox]{width:auto}.panel{border:1px solid #dce2d7;padding:15px;border-radius:8px;margin:15px 0}.panel input,.panel select{margin:5px}.event-row{display:flex;align-items:center;gap:14px;flex-wrap:wrap;width:100%;padding:18px;border-bottom:1px solid #dce2d7}.event-row label{display:flex;flex-direction:column}.error{color:#a33e29}footer{padding:25px 5%;border-top:1px solid #e1e5dc;font-size:11px;letter-spacing:2px;color:#8b9288}footer span{float:right}@media(max-width:700px){main{padding:20px 12px}.private{font-size:10px}header{gap:8px;padding:15px}.heading{align-items:start}h1{font-size:30px}h1 em{display:block;margin:0;font-size:17px}.cards{grid-template-columns:1fr}.calendar{min-width:700px}section:has(>.calendar){overflow:auto}.day{min-height:120px}nav{gap:10px}nav button{font-size:13px}.dialog{padding:22px}.toolbar{font-size:11px}.overlay{padding:10px}}
.chip{border-left:0;font-size:12px;padding:5px 8px}.dialog{font-size:12px}.dialog h2{font-size:20px}.dialog h3{font-size:14px}.dialog .banner strong{font-size:15px}.dialog .banner span{font-size:12px}.hero{padding-top:20px}.hero img{max-height:420px;width:100%;object-fit:contain}.poster-placeholder{height:260px;display:grid;place-items:center;background:#e3e9dc;color:#7c8974;border-radius:8px}.drama-month-heading{display:flex;gap:32px;align-items:center;margin:32px 0 40px}.drama-month-heading .year{letter-spacing:8px;color:#969696;font-size:14px}.drama-month-heading h2{font-size:88px;line-height:1.1;margin:0;color:#191919;font-weight:700;letter-spacing:-4px}.drama-month-heading small{font-size:46px;font-weight:400;letter-spacing:0;margin-left:28px;color:#999}.drama-month-heading button{background:none;border:0}.drama-month-heading .arrow{font-size:34px;color:#888}.drama-month-heading .today{margin-left:auto;border:1px solid #e4dfd9;border-radius:25px;padding:6px 22px;color:#888}@media(max-width:700px){.drama-month-heading{gap:8px}.drama-month-heading h2{font-size:48px}.drama-month-heading small{font-size:25px;margin-left:12px}.drama-month-heading .today{padding:5px 12px}}
